DEFAULT_DESCRIPTION = (
    "La respuesta presentó un indicio compatible con el manejo inseguro de una entrada o configuración; revisar la evidencia antes de confirmar el hallazgo.",
    "El impacto depende del componente, de los permisos y de la posibilidad real de explotación.",
    "Investigar el punto afectado, aplicar controles adecuados y repetir la prueba después de corregirlo.",
)


def descriptions(vulnerability_type):
    name = str(vulnerability_type).lower()
    for needles, *texts in DESCRIPTIONS:
        if any(needle in name for needle in needles):
            return texts
    return DEFAULT_DESCRIPTION
